function getQuestionBank(category: string): { q: string; o: string[]; a: number }[] {
  const cat = category.toLowerCase();
  if (cat.includes('tech') || cat.includes('software') || cat.includes('development') || cat.includes('frontend') || cat.includes('backend')) return QUESTION_BANKS.technology;
  if (cat.includes('business') || cat.includes('entrepreneur') || cat.includes('finance') || cat.includes('leadership')) return QUESTION_BANKS.business;
  if (cat.includes('design') || cat.includes('ui') || cat.includes('ux') || cat.includes('graphic') || cat.includes('fashion')) return QUESTION_BANKS.design;
  if (cat.includes('security') || cat.includes('cyber') || cat.includes('hack') || cat.includes('ethical')) return QUESTION_BANKS.security;
  if (cat.includes('data') || cat.includes('ai') || cat.includes('machine') || cat.includes('analytics') || cat.includes('python')) return QUESTION_BANKS.data;
  if (cat.includes('communicat') || cat.includes('speak') || cat.includes('public') || cat.includes('soft')) return QUESTION_BANKS.communication;
  if (cat.includes('wellness') || cat.includes('health') || cat.includes('fitness') || cat.includes('stress') || cat.includes('mental')) return QUESTION_BANKS.health;
  if (cat.includes('market') || cat.includes('social') || cat.includes('seo')) return QUESTION_BANKS.marketing;
  if (cat.includes('agric') || cat.includes('farm')) return QUESTION_BANKS.agriculture;
  if (cat.includes('culinary') || cat.includes('cook') || cat.includes('hospitality') || cat.includes('food')) return QUESTION_BANKS.health;
  if (cat.includes('language') || cat.includes('english') || cat.includes('french')) return QUESTION_BANKS.communication;
  if (cat.includes('educat') || cat.includes('teach') || cat.includes('kids') || cat.includes('child')) return QUESTION_BANKS.communication;
  if (cat.includes('trades') || cat.includes('engineer') || cat.includes('electrical') || cat.includes('plumb') || cat.includes('construct') || cat.includes('carpent')) return QUESTION_BANKS.technology;
  if (cat.includes('renewable') || cat.includes('solar') || cat.includes('energy')) return QUESTION_BANKS.technology;
  return QUESTION_BANKS.technology;
}

