function getModuleTopics(category: string, level: string): string[] {
  const cat = category.toLowerCase();
  if (cat.includes('tech') || cat.includes('software') || cat.includes('development') || cat.includes('it')) return MODULE_TOPIC_TEMPLATES.technology;
  if (cat.includes('business') || cat.includes('leadership') || cat.includes('management') || cat.includes('finance') || cat.includes('entrepreneur') || cat.includes('marketing')) return MODULE_TOPIC_TEMPLATES.business;
  if (cat.includes('design') || cat.includes('graphic') || cat.includes('ui') || cat.includes('ux') || cat.includes('fashion')) return MODULE_TOPIC_TEMPLATES.design;
  if (cat.includes('security') || cat.includes('cyber') || cat.includes('hack')) return MODULE_TOPIC_TEMPLATES.security;
  if (cat.includes('data') || cat.includes('ai') || cat.includes('machine') || cat.includes('analytics') || cat.includes('python')) return MODULE_TOPIC_TEMPLATES.data;
  if (cat.includes('communicat') || cat.includes('speak') || cat.includes('public') || cat.includes('soft')) return MODULE_TOPIC_TEMPLATES.communication;
  if (cat.includes('market') || cat.includes('social media') || cat.includes('seo')) return MODULE_TOPIC_TEMPLATES.marketing;
  if (cat.includes('agric') || cat.includes('farm')) return MODULE_TOPIC_TEMPLATES.agriculture;
  if (cat.includes('health') || cat.includes('wellness') || cat.includes('fitness') || cat.includes('stress') || cat.includes('mental')) return MODULE_TOPIC_TEMPLATES.healthcare;
  if (cat.includes('culinary') || cat.includes('cook') || cat.includes('hospitality') || cat.includes('food')) return MODULE_TOPIC_TEMPLATES.culinary;
  if (cat.includes('language') || cat.includes('english') || cat.includes('french')) return MODULE_TOPIC_TEMPLATES.languages;
  if (cat.includes('renewable') || cat.includes('solar') || cat.includes('energy')) return MODULE_TOPIC_TEMPLATES.renewable;
  if (cat.includes('education') || cat.includes('teach') || cat.includes('kids') || cat.includes('child')) return MODULE_TOPIC_TEMPLATES.education;
  if (cat.includes('engineer') || cat.includes('electrical') || cat.includes('plumb') || cat.includes('construct') || cat.includes('carpent') || cat.includes('trade')) return MODULE_TOPIC_TEMPLATES.technology;
  return MODULE_TOPIC_TEMPLATES.technology;
}

function getLessonTitle(moduleTitle: string, lessonIndex: number): string {
  const lessonTitles = [
    `${moduleTitle}: Key Concepts`,
    `${moduleTitle}: Practical Applications`,
    `${moduleTitle}: Case Studies and Examples`,
    `${moduleTitle}: Best Practices and Tips`,
    `${moduleTitle}: Quiz`,
  ];
  return lessonTitles[lessonIndex] || `${moduleTitle}: Lesson ${lessonIndex + 1}`;
}

function getQuizQuestions(moduleIndex: number, category: string, count: number = 5): { questionText: string; type: string; options: string[]; correctOptionIndex: number }[] {
  const bank = getQuestionBank(category);
  const questions: { questionText: string; type: string; options: string[]; correctOptionIndex: number }[] = [];

  // Use module-specific questions
  for (let i = 0; i < count; i++) {
    const qIndex = (moduleIndex * 5 + i) % bank.length;
    const q = bank[qIndex];
    questions.push({
      questionText: q.q,
      type: 'multiple_choice',
      options: q.o,
      correctOptionIndex: q.a,
    });
  }
  return questions;
}

function getFinalExamQuestions(category: string, count: number = 25): { questionText: string; type: string; options?: string[]; correctOptionIndex?: number; points: number }[] {
  const bank = getQuestionBank(category);
  const questions: { questionText: string; type: string; options?: string[]; correctOptionIndex?: number; points: number }[] = [];

  for (let i = 0; i < Math.min(count, bank.length); i++) {
    const q = bank[i];
    questions.push({
      questionText: q.q,
      type: 'mcq',
      options: q.o,
      correctOptionIndex: q.a,
      points: count > 20 ? 4 : Math.round(100 / count),
    });
  }

  // Add open-ended questions
  questions.push(
    { questionText: `Explain how the concepts learned in this course can be applied in real-world scenarios. Provide specific examples.`, type: 'open', points: 20 },
    { questionText: `Describe a challenge you might face when applying these skills and how you would overcome it.`, type: 'open', points: 20 },
    { questionText: `What are the most important ethical considerations in this field?`, type: 'open', points: 20 },
    { questionText: `How would you teach these concepts to a beginner? Outline your approach.`, type: 'open', points: 20 },
    { questionText: `Reflect on how this course has changed your understanding of the subject.`, type: 'open', points: 20 },
  );

  return questions;
}

function generateContentModules(courseTitle: string, category: string, level: string): any[] {
  const topics = getModuleTopics(category, level);
  const modules: any[] = [];

  for (let m = 0; m < 20; m++) {
    const topic = topics[m % topics.length];
    const moduleTitle = `Module ${m + 1}: ${topic}`;
    const lessons: any[] = [];

    // 4 content lessons
    for (let l = 0; l < 4; l++) {
      const lessonTitle = getLessonTitle(topic, l);
      lessons.push({
        title: lessonTitle,
        content: `<div class="lesson-content">
<h2>${lessonTitle}</h2>
<p>Welcome to <strong>${lessonTitle}</strong> part of <em>${courseTitle}</em>.</p>
<p>In this lesson, we will explore key concepts related to <strong>${topic.toLowerCase()}</strong>. Understanding these fundamentals is essential for building a strong foundation in this field.</p>

<h3>Learning Objectives</h3>
<ul>
  <li>Understand the core principles of ${topic.toLowerCase()}</li>
  <li>Apply these concepts to practical scenarios</li>
  <li>Analyze real-world examples and case studies</li>
  <li>Evaluate best practices and common pitfalls</li>
</ul>

<h3>Key Concepts</h3>
<p>${topic} is a critical area of study in ${category}. It encompasses a range of topics from fundamental principles to advanced applications. By mastering these concepts, you will be better equipped to tackle complex challenges in your professional journey.</p>

<h3>Practical Application</h3>
<p>Take time to practice these concepts through hands-on exercises. Apply what you have learned to your own projects or work environment. Remember that consistent practice is the key to mastery.</p>

<h3>Summary</h3>
<p>In this lesson, we covered the essential aspects of ${topic.toLowerCase()}. The next lesson will build on these foundations and explore more advanced topics.</p>
</div>`,
        duration: Math.floor(Math.random() * 15) + 10,
        type: l % 2 === 0 ? 'video' : 'article',
        videoUrl: l % 2 === 0 ? `https://www.youtube.com/watch?v=example_${m}_${l}` : undefined,
        resources: [],
      });
    }

    // Quiz lesson (5th lesson)
    const quizLesson: any = {
      title: `${topic} — Module Quiz`,
      content: `<p>Test your knowledge of <strong>${topic}</strong>. Answer all questions to complete this module.</p>`,
      type: 'quiz',
      duration: 15,
      quizQuestions: getQuizQuestions(m, category, 5),
      quizConfig: {
        timeLimit: 15,
        quizType: 'exercise',
        questionsPerPage: 5,
      },
    };
    lessons.push(quizLesson);

    modules.push({
      title: moduleTitle,
      description: `Explore ${topic.toLowerCase()} in depth. This module covers key concepts, practical applications, and includes a quiz to test your understanding.`,
      lessons,
    });
  }

  return modules;
}

function generateFinalExamModule(category: string): any {
  return {
    title: 'Final Exam — Course Certification Assessment',
    description: 'Comprehensive final examination covering all 20 modules of the course. You must score at least 70% to pass and receive your certificate.',
    lessons: [
      {
        title: 'Final Exam',
        content: '<p>This final exam tests your knowledge across all modules of this course. You have 60 minutes to complete it. A minimum score of 70% is required to pass.</p><p><strong>Instructions:</strong></p><ul><li>Read each question carefully before answering</li><li>You cannot pause the timer once started</li><li>Do not use external resources during the exam</li><li>Multiple choice questions have one correct answer</li><li>Open-ended questions require thoughtful, well-written responses</li></ul>',
        type: 'assignment',
        duration: 60,
        isAssignment: true,
        requiredAssignment: true,
        assignmentConfig: {
          timeLimit: 60,
          allowRetakes: false,
          disableRightClick: true,
          mode: 'exam',
        },
        assignmentQuestions: getFinalExamQuestions(category, 25),
      },
    ],
  };
}

