// ─── Main Seeding Function ───────────────────────────────────────────────────

async function seedEnhanceCourses() {
  try {
    await connectDB();
    console.log('\n🚀 STARTING COURSE ENHANCEMENT SEED\n');

    // Find an admin/trainer for the instructor reference
    const instructor = await User.findOne({ role: { $in: ['trainer', 'admin', 'super_admin'] } });
    if (!instructor) {
      console.error('❌ No trainer/admin found in database. Please seed users first.');
      process.exit(1);
    }

    let createdCount = 0;
    let updatedCount = 0;
    let skippedCount = 0;

    for (const courseDef of COURSES_TO_ENHANCE) {
      console.log(`\n📚 Processing: "${courseDef.title}"`);

      // Check if course already exists
      let existingCourse = await Course.findOne({ title: courseDef.title });

      // Generate 20 content modules + final exam module
      const modules = generateContentModules(courseDef.title, courseDef.category, courseDef.level);
      const finalExam = generateFinalExamModule(courseDef.category);
      modules.push(finalExam);

      const courseData = {
        title: courseDef.title,
        description: `<p>${courseDef.description}</p>`,
        thumbnail: courseDef.thumbnail,
        instructor: instructor._id,
        createdBy: instructor._id,
        price: courseDef.price,
        discountPrice: courseDef.price > 0 ? Math.round(courseDef.price * 0.9) : 0,
        level: courseDef.level,
        category: courseDef.category,
        school: courseDef.school,
        status: 'published',
        enrollmentMode: 'direct',
        allowedDeliveryModes: ['online'],
        modules: modules,
      } as any;

      if (existingCourse) {
        // Update existing course
        existingCourse.description = courseData.description;
        existingCourse.thumbnail = courseData.thumbnail;
        existingCourse.price = courseData.price;
        existingCourse.discountPrice = courseData.discountPrice;
        existingCourse.level = courseData.level;
        existingCourse.category = courseData.category;
        existingCourse.school = courseData.school;
        (existingCourse as any).modules = courseData.modules;
        await existingCourse.save();
        console.log(`   ✅ Updated: ${courseDef.title}`);
        console.log(`   📦 Modules: ${modules.length} (20 content + 1 final exam)`);
        console.log(`   📝 Total lessons: ${modules.reduce((sum: number, m: any) => sum + m.lessons.length, 0)}`);
        updatedCount++;
      } else {
        await new Course(courseData).save();
        console.log(`   ✅ Created: ${courseDef.title}`);
        console.log(`   📦 Modules: ${modules.length} (20 content + 1 final exam)`);
        console.log(`   📝 Total lessons: ${modules.reduce((sum: number, m: any) => sum + m.lessons.length, 0)}`);
        createdCount++;
      }
    }

    console.log(`\n═════════════════════════════════════`);
    console.log(`🏁 COURSE ENHANCEMENT COMPLETE!`);
    console.log(`   ✅ Created: ${createdCount} courses`);
    console.log(`   🔄 Updated: ${updatedCount} courses`);
    console.log(`   ⏭️  Skipped: ${skippedCount} courses`);
    console.log(`   📚 Total courses processed: ${createdCount + updatedCount}`);
    console.log(`   Each course has: 20 content modules + 1 final exam module`);
    console.log(`   Each module has: 4 content lessons + 1 quiz`);
    console.log(`   Final exam has: 25+ questions`);
    console.log(`═════════════════════════════════════\n`);

    await mongoose.disconnect();
    process.exit(0);
  } catch (error) {
    console.error('❌ Error during course enhancement:', error);
    process.exit(1);
  }
}

seedEnhanceCourses();
